SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "李茂贞辞朝还镇。", "citation": "卷262·天复元年（901）·zztj-v262-y0901-p009·原文件第48行", "note": "原文：李茂贞辞还镇。；核对说明：按原文动作分录，不外推结果。", "status": "draft", "id": "4922925d-f9b6-5432-8ce5-b8b6f21e14cb", "subject_id": "d7b15e51-a271-507c-b285-f0da94e44da4", "source_id": "1336e49a-a879-57f6-81df-7db57d1c7613"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "901年正月后；确日未载", "citation": "卷262·天复元年（901）·zztj-v262-y0901-p009·原文件第48行", "note": "原文：李茂贞辞还镇。；核对说明：沿主书段落次序；干支日未换算公历日。", "status": "draft", "id": "56e21743-dbc8-5161-abfa-11e2d838ff4e", "subject_id": "d7b15e51-a271-507c-b285-f0da94e44da4", "source_id": "1336e49a-a879-57f6-81df-7db57d1c7613"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记李茂贞：辞朝还镇者。", "citation": "卷262·天复元年（901）·zztj-v262-y0901-p009·原文件第48行", "note": "原文：李茂贞辞还镇。崔胤以宦官典兵，终为肘腋之患，欲以外兵制之，讽茂贞留兵三千于京师，充宿卫，以茂贞假子继筠将之。左谏议大夫万年韩偓以为不可，胤曰：“兵自不肯去，非留之也。”偓曰：“始者何为召之邪？”胤无以应。偓曰：“留此兵则家国两危，不留则家国两安。”胤不从。；核对说明：只据本段确认参与身份；同名与异体字回查后复用。", "status": "draft", "id": "cb106b76-43ef-53cc-9a63-84eee7014bc5", "subject_id": "af9a00d1-c748-5b5f-9175-1af19530d83d", "source_id": "1336e49a-a879-57f6-81df-7db57d1c7613"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李茂贞：辞朝还镇者。", "citation": "卷262·天复元年（901）·zztj-v262-y0901-p009·原文件第48行", "note": "原文：李茂贞辞还镇。；核对说明：参与身份依据本段措辞，不因同场出现推定额外关系。", "status": "draft", "id": "c46a1d69-4141-55aa-85c5-0af77108451a", "subject_id": "0f00c47a-79a3-514f-bc43-0b35e51bb58f", "source_id": "1336e49a-a879-57f6-81df-7db57d1c7613"}, {"subject_table": "event", "field_path": "description", "claim_text": "崔胤请留凤翔兵三千宿卫京师。", "citation": "卷262·天复元年（901）·zztj-v262-y0901-p009·原文件第48行", "note": "原文：讽茂贞留兵三千于京师，充宿卫，以茂贞假子继筠将之。；核对说明：三千是崔胤所求驻兵；假子明确为李茂贞之假子，未据此推定正式收养仪式。", "status": "draft", "id": "2bbf93bb-757